//! The plugin module ABI (plan 4.3). A plugin module imports `env.memory` (host-owned, fixed maximum),
//! may import `env.abort` and `env.log`, and exports exactly the four functions named below. Calls move
//! bytes only: the host writes a call frame into memory obtained from `valley_alloc`, calls `valley_call`,
//! reads the response frame it returns and releases both with `valley_free`.
//!
//! This crate has no dependencies so it can be vendored unchanged; the raw `extern "C"` exports are
//! generated by plugin-tools (Step 12.3) on top of these definitions.
#![forbid(unsafe_code)]

/// Bumped on any change to the export set or the frame layout.
pub const ABI_VERSION: u32 = 1;

pub const EXPORT_ABI_VERSION: &str = "valley_abi_version";
pub const EXPORT_ALLOC: &str = "valley_alloc";
pub const EXPORT_FREE: &str = "valley_free";
pub const EXPORT_CALL: &str = "valley_call";
pub const EXPORTS: [&str; 4] = [EXPORT_ABI_VERSION, EXPORT_ALLOC, EXPORT_FREE, EXPORT_CALL];

/// The only imports a module may declare, as (module, name).
pub const IMPORTS: [(&str, &str); 3] = [("env", "memory"), ("env", "abort"), ("env", "log")];

/// Longest method name a call frame may carry.
pub const MAX_METHOD_BYTES: usize = 256;

/// `valley_call` packs the response frame's location into one `u64`: pointer in the high half, length in the low half.
#[must_use]
pub fn pack_region(ptr: u32, len: u32) -> u64 {
    (u64::from(ptr) << 32) | u64::from(len)
}

#[must_use]
pub fn unpack_region(packed: u64) -> (u32, u32) {
    ((packed >> 32) as u32, (packed & 0xffff_ffff) as u32)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FrameError {
    Truncated,
    MethodTooLong,
    MethodNotUtf8,
    UnknownStatus(u8),
}

/// Call frame: `u16` little-endian method length, the UTF-8 method name, then the payload bytes.
///
/// # Errors
/// `FrameError::MethodTooLong` when `method` is longer than `MAX_METHOD_BYTES`.
pub fn encode_call(method: &str, payload: &[u8]) -> Result<Vec<u8>, FrameError> {
    let len = u16::try_from(method.len()).map_err(|_| FrameError::MethodTooLong)?;
    if method.len() > MAX_METHOD_BYTES {
        return Err(FrameError::MethodTooLong);
    }
    let mut frame = Vec::with_capacity(2 + method.len() + payload.len());
    frame.extend_from_slice(&len.to_le_bytes());
    frame.extend_from_slice(method.as_bytes());
    frame.extend_from_slice(payload);
    Ok(frame)
}

/// # Errors
/// A `FrameError` naming the first malformed part.
pub fn decode_call(frame: &[u8]) -> Result<(&str, &[u8]), FrameError> {
    let (head, rest) = frame.split_first_chunk::<2>().ok_or(FrameError::Truncated)?;
    let len = usize::from(u16::from_le_bytes(*head));
    if len > MAX_METHOD_BYTES {
        return Err(FrameError::MethodTooLong);
    }
    let (method, payload) = rest.split_at_checked(len).ok_or(FrameError::Truncated)?;
    let method = std::str::from_utf8(method).map_err(|_| FrameError::MethodNotUtf8)?;
    Ok((method, payload))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Status {
    Ok = 0,
    Error = 1,
}

/// Response frame: one status byte, then the payload (result bytes, or a UTF-8 error message).
#[must_use]
pub fn encode_response(status: Status, payload: &[u8]) -> Vec<u8> {
    let mut frame = Vec::with_capacity(1 + payload.len());
    frame.push(status as u8);
    frame.extend_from_slice(payload);
    frame
}

/// # Errors
/// `FrameError::Truncated` for an empty frame, `FrameError::UnknownStatus` for any other status byte.
pub fn decode_response(frame: &[u8]) -> Result<(Status, &[u8]), FrameError> {
    let (&status, payload) = frame.split_first().ok_or(FrameError::Truncated)?;
    let status = match status {
        0 => Status::Ok,
        1 => Status::Error,
        other => return Err(FrameError::UnknownStatus(other)),
    };
    Ok((status, payload))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn call_frames_round_trip() {
        for (method, payload) in [
            ("layout.tick", &b"\x00\x01\x02"[..]),
            ("", &b""[..]),
            ("ünïcode", &[0xff; 300][..]),
        ] {
            let frame = encode_call(method, payload).unwrap();
            assert_eq!(decode_call(&frame).unwrap(), (method, payload));
        }
    }

    #[test]
    fn response_frames_round_trip() {
        for status in [Status::Ok, Status::Error] {
            let frame = encode_response(status, b"result");
            assert_eq!(decode_response(&frame).unwrap(), (status, &b"result"[..]));
        }
    }

    #[test]
    fn regions_round_trip() {
        for (ptr, len) in [(0, 0), (1, u32::MAX), (u32::MAX, 7)] {
            assert_eq!(unpack_region(pack_region(ptr, len)), (ptr, len));
        }
    }

    #[test]
    fn malformed_frames_are_rejected() {
        assert_eq!(decode_call(b"\x01"), Err(FrameError::Truncated));
        assert_eq!(decode_call(b"\x05\x00abc"), Err(FrameError::Truncated));
        assert_eq!(decode_call(b"\x01\x00\xff"), Err(FrameError::MethodNotUtf8));
        assert_eq!(decode_call(&[0x01, 0x01]), Err(FrameError::MethodTooLong));
        assert_eq!(
            encode_call(&"m".repeat(MAX_METHOD_BYTES + 1), b""),
            Err(FrameError::MethodTooLong)
        );
        assert_eq!(decode_response(b""), Err(FrameError::Truncated));
        assert_eq!(decode_response(b"\x02"), Err(FrameError::UnknownStatus(2)));
    }

    #[test]
    fn the_export_and_import_sets_are_fixed() {
        assert_eq!(
            EXPORTS,
            ["valley_abi_version", "valley_alloc", "valley_free", "valley_call"]
        );
        assert_eq!(IMPORTS[0], ("env", "memory"));
    }
}
